return ['x-generator'=>'GlotPress/4.0.1','translation-revision-date'=>'2025-03-05 18:08:41+0000','plural-forms'=>'nplurals=2; plural=n > 1;','project-id-version'=>'Plugins - LiveJournal Importer - Stable (latest release)','language'=>'pt_BR','messages'=>['http://wordpress.org/'=>'http://br.wordpress.org/','wordpressdotorg'=>'wordpressdotorg','Import posts and comments from LiveJournal.'=>'Importa posts e comentários do LiveJournal.','http://wordpress.org/extend/plugins/livejournal-importer/'=>'https://br.wordpress.org/plugins/livejournal-importer/','LiveJournal Importer'=>'Importador do LiveJournal','Import posts from LiveJournal using their API.'=>'Importar posts do LiveJournal usando a API.','LiveJournal'=>'LiveJournal','Processing next batch.'=>'Processando o próximo lote.','Continuing&#8230;'=>'Continuando&#8230;','Continuing in %d&#8230;'=>'Continuando em %d&#8230;','All done. <a href="%s">Have fun!</a>'=>'Feito. <a href="%s">Divirta-se!</a>','Successfully re-threaded %s comments.'=>'%s comentários foram reaninhados com sucesso.','We are now re-building the threading of your comments (this can also take a while if you have lots of comments)...'=>'Agora nós estamos reconstruindo seus comentários aninhados (isto também pode levar um tempo se você possui muitos comentários)...','Threading Comments&#8230;'=>'Aninhando comentários&#8230;','Rebuild my comment threads &raquo;'=>'Reestruturar meus comentários aninhados &raquo;','Your comments have all been imported now, but we still need to rebuild your conversation threads.'=>'Os seus comentários foram todos importados agora, mas nós ainda precisamos reconstruir as conversas aninhadas.','Imported comment batch %d of <strong>approximately</strong> %d'=>'Foi importado o lote de comentários %d de <strong>aproximadamente</strong> %d','Now we will download your comments so we can import them (this could take a <strong>long</strong> time if you have lots of comments)...'=>'Agora vamos exportar seus comentários para que possamos importá-los posteriormente (isto pode levar um <strong>bom tempo</strong> se você tiver muitos comentários).','Downloading Comments&#8230;'=>'Exportando comentários&#8230;','Download my comments &raquo;'=>'Exportar meus comentários &raquo;','Your posts have all been imported, but wait &#8211; there&#8217;s more! Now we need to download &amp; import your comments.'=>'Os seus posts foram todos importados mas espere,  tem mais! Agora nós precisamos fazer a exportação e posterior importação dos seus comentários.','Import the next batch'=>'Importar o próximo lote','Try Again'=>'Tente novamente','We&#8217;ve saved where you were up to though, so if you come back to this importer in about 30 minutes, you should be able to continue from where you were.'=>'Mas nós gravamos o lugar até onde você chegou, assim se voltar para esta importação dentro de 30 minutos, você poderá continuar de onde parou.','Uh oh &ndash; LiveJournal has disconnected us because we made too many requests to their servers too quickly.'=>'Epa &ndash; O Live Journal nos desconectou porque nós fizemos muitas solicitações aos seus servidores muito rapidamente.','Imported post batch %d of <strong>approximately</strong> %d'=>'Importado lote de posts %d de <strong>aproximadamente</strong> %d','We&#8217;re downloading and importing your LiveJournal posts...'=>'Estamos fazendo a exportação e importando seus posts do LiveJournal...','Importing Posts'=>'Importando posts','Logging in to LiveJournal failed. Check your username and password and try again.'=>'Não foi possível fazer fazer acesso ao LiveJournal. Verifique o seu nome de usuário e senha e tente novamente.','Start again'=>'Iniciar de novo','Please enter your LiveJournal username <em>and</em> password so we can download your posts and comments.'=>'Insira o nome e a senha de usuário do LiveJournal para realizar a exportação dos posts e comentários.','XML-RPC Request Failed -- '=>'O pedido XML-RPC falhou -- ','LiveJournal is not responding to authentication requests. Please wait a while and then try again.'=>'O LiveJournal não está respondendo às solicitações de autenticação. Aguarde um pouco e tente novamente.','Anonymous'=>'Anônimo','Failed to retrieve comment bodies from LiveJournal. Please try again soon.'=>'Não foi possível recuperar os somentários do LiveJournal. Tente novamente logo.','Comment metadata downloaded successfully, proceeding with comment bodies...'=>'Os metadados dos comentários foram exportados com sucesso, prosseguindo com o conteúdo dos comentários...','You have no comments to import!'=>'Você não possui comentários para importar!','Failed to retrieve comment meta information from LiveJournal. Please try again soon.'=>'Não foi possível recuperar meta-informações dos comentários do LiveJournal. Tente novamente logo.','Could not get a cookie from LiveJournal. Please try again soon.'=>'Não foi possível obter um cookie do LiveJournal. Tente novamente.','Failed to create post.'=>'Falha ao criar post.','Couldn&#8217;t get post ID (creating post failed!)'=>'Não foi possível obter a ID do post (falha ao criar o post!)','Imported post <strong>%s</strong>...'=>'Post <strong>%s</strong> importado...','Post <strong>%s</strong> already exists.'=>'O post <strong>%s</strong> já existe.','Post metadata has been downloaded, proceeding with posts...'=>'A exportação dos metadados dos posts foram concluídos, prosseguindo com o conteúdo dos posts...','<strong>NOTE:</strong> You appear to have JavaScript disabled, so you will need to manually click through each step of this importer. If you enable JavaScript, it will step through automatically.'=>'<strong>NOTA:</strong> Parece que o Javascript está desativado, então você terá que clicar manualmente em cada etapa desta importação. Se você ativar o Javascript, ela avançará automaticamente.','<strong>NOTE:</strong> If the import process is interrupted for <em>any</em> reason, come back to this page and it will continue from where it stopped automatically.'=>'<strong>NOTA:</strong> Se o processo de importação for interrompido por <em>qualquer</em> razão, volte para esta página e automaticamente ele continuará de onde parou.','Connect to LiveJournal and Import'=>'Conectar ao LiveJournal e importar','<strong>WARNING:</strong> This can take a really long time if you have a lot of entries in your LiveJournal, or a lot of comments. Ideally, you should only start this process if you can leave your computer alone while it finishes the import.'=>'<strong>ATENÇÃO:</strong> Isto pode levar bastante tempo se houver muitas entradas ou muitos comentários no seu blog LiveJournal. O ideal é que você comece este processo se puder deixar seu computador trabalhando sozinho até terminar a importação.','Protected Post Password'=>'Senha do post protegido','Enter the password you would like to use for all protected entries here:'=>'Insira a senha que você gostaria de usar para todas as entradas protegidas aqui:','If you don&#8217;t enter a password, ALL ENTRIES from your LiveJournal will be imported as public posts in WordPress.'=>'Se você não inserir uma senha, TODAS AS ENTRADAS do seu LiveJournal serão importadas como posts públicos no WordPress.','If you have any entries on LiveJournal which are marked as private, they will be password-protected when they are imported so that only people who know the password can see them.'=>'Se você possui alguma entrada no LiveJournal que esteja marcada como privada, elas serão protegidas por senha quando forem importadas para que somente quem saiba a senha possa vê-las.','LiveJournal Password'=>'Senha do LiveJournal','LiveJournal Username'=>'Nome de usuário do LiveJournal','Enter your LiveJournal username and password below so we can connect to your account:'=>'Insira abaixo o seu nome de usuário e senha do LiveJournal para que nós possamos conectá-lo a sua conta:','Howdy! This importer allows you to connect directly to LiveJournal and download all your entries and comments'=>'Olá! Este importador permite que você se conecte diretamente ao LiveJournal e faça o download de suas entradas e comentários','Cancel &amp; start a new import'=>'Cancelar e iniciar uma nova importação','Continue previous import'=>'Continuar a importação anterior','It looks like you attempted to import your LiveJournal posts previously and got interrupted.'=>'Parece que você tentou importar os posts do LiveJournal antes e foi interrompido.','Import LiveJournal'=>'Importar do LiveJournal']];